export function topKFrequent(words: string[], k: number): string[] {
const counts=new Map<string,number>();for(const w of words)counts.set(w,(counts.get(w)??0)+1);return [...counts.keys()].sort((a,b)=>counts.get(b)!-counts.get(a)!||(a<b?-1:a>b?1:0)).slice(0,k);
}
